package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;
/** Synthetic Android WebView coverage, never a real account or user database. */
public final class VisualEditorTest extends DocumentEditorTest {
 @Override void input(String title,String note)throws Exception{h.js("document.querySelector('#doc-title').value="+JSONObject.quote(title)+";document.querySelector('#doc-title').dispatchEvent(new Event('input'));document.querySelector('#doc-body').innerHTML='';document.querySelector('#doc-body').append(DocumentRich.render("+JSONObject.quote(note)+",()=>''));document.querySelector('#doc-body').dispatchEvent(new Event('input'))");}
 String body="第一段：原有 **加粗** 和 *强调*。\n\n## 二级标题\n\n- 第一项\n- 第二项\n\n```java\nint a = 1;\n```\n\n| 项目 | 数值 |\n| --- | --- |\n| 阅读 | 12 |\n\n[安全链接](https://example.com)\n\n<script>not executable</script>\n";
 void selectText(String needle)throws Exception{h.js("(()=>{const b=document.querySelector('#doc-body'),w=document.createTreeWalker(b,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){const at=n.textContent.indexOf("+JSONObject.quote(needle)+");if(at>=0){const r=document.createRange();r.setStart(n,at);r.setEnd(n,at+"+needle.length()+");b.focus();getSelection().removeAllRanges();getSelection().addRange(r);document.dispatchEvent(new Event('selectionchange'));return true;}}throw Error('selection missing')})()");Thread.sleep(300);}
 String source()throws Exception{return new JSONArray("["+h.js("DocumentRich.serialize(document.querySelector('#doc-body'))")+"]").getString(0);}
 @Override public void onStart(){Bundle result=new Bundle();try{
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");
  if(phase.equals("seed")){
   check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.10.0"),"Seed actual previous 1.10.0 signed APK");
   h.call("saveRecord",new JSONObject().put("record",new JSONObject().put("id","visual-upgrade").put("type","learning").put("date","2026-10-01").put("title","历史格式笔记").put("note",body).put("durationMinutes",37).put("masteryLevel","familiar").put("evidenceType","none").put("evidenceNote","历史证据原样保留").put("tags",new JSONArray().put("历史标签"))));
   try(FileOutputStream out=getTargetContext().openFileOutput("visual-upgrade.json",0)){out.write(state().toString().getBytes("UTF-8"));}
  }else{
   check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.10.5"),"New signed APK starts");
   if(phase.equals("verify")){JSONObject old=new JSONObject(new String(java.nio.file.Files.readAllBytes(new File(getTargetContext().getFilesDir(),"visual-upgrade.json").toPath()),"UTF-8")),now=state();for(String key:new String[]{"records","settings","messages","wikiPages"})check(old.get(key).toString().equals(now.get(key).toString()),"Cover install preserves "+key);}
   h.js("RecordEditor.open("+record("visual-upgrade")+")");until("!!document.querySelector('#doc-body')");Thread.sleep(300);
   check(source().equals(body),"Unedited original Markdown round-trips byte for byte: "+source());
   check(h.js("!!document.querySelector('#doc-body strong')&&!!document.querySelector('#doc-body li')&&!!document.querySelector('#doc-body table')&&!!document.querySelector('#doc-body pre')").equals("true"),"Existing bold, list, table and code render visually");
   check(h.js("!document.querySelector('#doc-body script')&&!document.querySelector('#doc-body [onclick]')").equals("true"),"HTML-like notes never execute or create active HTML");
   click("#doc-info");check(h.js("document.querySelectorAll('[data-meta=masteryLevel],[data-meta=evidenceType],[data-meta=evidenceNote]').length===0").equals("true"),"Learning metadata has no proficiency / evidence controls");click("#doc-meta-done");saveUI();
   JSONObject saved=record("visual-upgrade");check(saved.getString("note").equals(body),"Save without body changes preserves full original Markdown");check(saved.getString("masteryLevel").equals("familiar")&&saved.getString("evidenceType").equals("none")&&saved.getString("evidenceNote").equals("历史证据原样保留"),"Removing controls does not rewrite historical proficiency / evidence");
   open("learning");Thread.sleep(250);check(h.js("document.querySelector('#doc-title').getBoundingClientRect().height<=40").equals("true"),"Empty title occupies one compact line: "+h.js("(()=>{const t=document.querySelector('#doc-title'),s=getComputedStyle(t);return [t.clientHeight,t.scrollHeight,t.style.height,s.height,s.minHeight,s.padding,s.lineHeight,s.flex,s.margin]})()"));
   h.js("document.querySelector('#doc-title').focus()");check(h.js("getComputedStyle(document.querySelector('#doc-title')).outlineStyle==='none'").equals("true"),"Focused title has no giant outline");
   input("可视化排版测试","今天学习中文与emoji😀，保留全部正文。");selectText("中文与emoji😀");h.tap("[data-doc-command=bold]",false);Thread.sleep(250);
   check(h.js("document.querySelector('#doc-body b,#doc-body strong')?.textContent").equals(JSONObject.quote("中文与emoji😀")),"Actual toolbar touch formats the selected Chinese / emoji, not the whole note: "+h.js("[document.querySelector('#doc-body').innerHTML,getSelection().toString(),document.activeElement.id]"));
   check(h.js("!document.querySelector('#doc-body').textContent.includes('**')").equals("true"),"Bold markers are invisible in editing surface");check(source().contains("**中文与emoji😀**"),"Visual bold persists as canonical portable Markdown");
   h.tap("[data-doc-command=bold]",false);Thread.sleep(150);check(!source().contains("**中文与emoji😀**"),"Second bold touch toggles selection back to normal");
   input("列表与标题","第一行正文\n第二行正文");h.js("(()=>{const b=document.querySelector('#doc-body'),r=document.createRange();r.selectNodeContents(b);b.focus();getSelection().removeAllRanges();getSelection().addRange(r);document.dispatchEvent(new Event('selectionchange'));})()");Thread.sleep(300);h.tap("[data-doc-command=insertUnorderedList]",false);Thread.sleep(250);
   check(h.js("document.querySelectorAll('#doc-body li').length>=1").equals("true"),"Multiline selection becomes visual list");check(source().contains("- ")&&h.js("document.querySelector('#doc-body').textContent").contains("第二行正文"),"List serialization preserves original multiline text");
   h.tap("[data-doc-command=insertUnorderedList]",false);Thread.sleep(150);check(h.js("document.querySelectorAll('#doc-body li').length===0").equals("true"),"List can be toggled off: "+h.js("[document.querySelector('#doc-body').innerHTML,getSelection().toString(),document.querySelector('.document-top').getBoundingClientRect().top,document.querySelector('#editor').scrollTop,window.scrollY]"));
   input("段落标题","要点标题");selectText("要点标题");h.tap("[data-doc-command=heading]",false);Thread.sleep(150);check(h.js("!!document.querySelector('#doc-body h2')").equals("true")&&source().contains("## 要点标题"),"Heading toolbar applies real heading without visible hashes");
   h.tap("[data-doc-command=heading]",false);Thread.sleep(150);check(h.js("!document.querySelector('#doc-body h2')").equals("true"),"Heading toggles back to normal paragraph");
   // A collapsed caret controls subsequent typing, not a literal ** insertion.
   input("光标格式","开头");h.js("(()=>{const b=document.querySelector('#doc-body'),r=document.createRange();r.selectNodeContents(b);r.collapse(false);b.focus();getSelection().removeAllRanges();getSelection().addRange(r);document.dispatchEvent(new Event('selectionchange'));})()");Thread.sleep(300);h.tap("[data-doc-command=bold]",false);Thread.sleep(350);h.js("document.execCommand('insertText',false,'新输入')");check(source().contains("**新输入**"),"Collapsed caret applies bold to subsequently typed text: "+source()+"; "+h.js("[document.querySelector('#doc-body').innerHTML,document.queryCommandState('bold')]"));
   // Pasting arbitrary HTML is treated as plain text, never trusted DOM.
   h.js("(()=>{const event=new Event('paste',{bubbles:true,cancelable:true});event.clipboardData={files:[],getData:()=>'<img src=x onerror=alert(1)>粘贴内容'};document.querySelector('#doc-body').dispatchEvent(event);})()");check(h.js("!document.querySelector('#doc-body img')&&document.querySelector('#doc-body').textContent.includes('粘贴内容')").equals("true"),"Paste discards HTML and executable image attributes");
   input("紧凑的学习笔记","今天阅读了数据治理文章。\n选中文字，再点击加粗或列表即可。\n下一步：完成一个实践案例。");selectText("数据治理");h.tap("[data-doc-command=bold]",false);h.js("document.querySelector('#doc-body').focus()");Thread.sleep(500);
   check(h.js("document.querySelector('#doc-tools').getBoundingClientRect().bottom<=innerHeight+1 && document.documentElement.scrollWidth<=innerWidth+1").equals("true"),"Toolbar stays above keyboard without horizontal overflow");check(h.js("document.querySelectorAll('#doc-tools button').length===5").equals("true"),"Five compact tools replace overflowing pill row");
   check(h.web.getScrollY()==0,"Native WebView keeps header visible above keyboard: scrollY="+h.web.getScrollY());h.screenshot("visual-editor-keyboard.png");click("#doc-more");check(h.js("!document.querySelector('#doc-more-panel').hidden && document.querySelector('#doc-complete').getBoundingClientRect().right<=innerWidth").equals("true"),"More panel exposes full readable AI / draft actions");click("#doc-more");
   String expected=source();saveUI();JSONArray all=records();JSONObject current=null;for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optString("title").equals("紧凑的学习笔记"))current=all.getJSONObject(i);if(current==null)throw new Exception("Rich record missing");check(current.getString("note").equals(expected),"Rich note is committed without losing text or formatting");
   h.js("RecordEditor.open("+current+")");until("!!document.querySelector('#doc-body strong') || !!document.querySelector('#doc-body b')");check(h.js("document.querySelector('#doc-body').textContent").contains("实践案例"),"Saved rich note reopens with visible styling and complete body");close();
   // Untouched complex paragraphs survive edits in a different block.
   h.js("RecordEditor.open("+record("visual-upgrade")+")");until("!!document.querySelector('#doc-body strong')");selectText("第一段");h.tap("[data-doc-command=bold]",false);check(source().contains("```java\nint a = 1;")&&source().contains("| --- | --- |"),"Editing one block retains untouched code language and table source exactly");close();
   // Title grows with actual content rather than reserving empty rows.
   open("experience");h.js("document.querySelector('#doc-title').value='这是一段很长的标题'.repeat(8);document.querySelector('#doc-title').dispatchEvent(new Event('input'))");check(h.js("document.querySelector('#doc-title').scrollHeight<=document.querySelector('#doc-title').clientHeight+1&&document.querySelector('#doc-title').clientHeight>40").equals("true"),"Long title expands without clipping or a fixed-height box");close();
  }
  result.putString("stream","PASS VisualEditorTest "+phase+": "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable err){try{if(h!=null)h.screenshot("visual-failure.png");}catch(Exception ignored){}result.putString("stream","FAIL VisualEditorTest after "+passed+": "+err+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
